"""Self-contained dashboard markup for the local test server."""

PAGE = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Connectivity Lab · Android Bluetooth & Wi-Fi</title>
<style>
:root{color-scheme:light;--ink:#142b3b;--muted:#687986;--line:#dce5e8;--paper:#fff;--canvas:#f1f6f7;--teal:#087e82;--teal-dark:#08676b;--blue:#e6f3f4;--green:#18734b;--red:#b3362d;--amber:#946719;--shadow:0 12px 34px #13324710;font-family:Inter,"Segoe UI",system-ui,sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink)}button,input,select{font:inherit}button{cursor:pointer}.shell{max-width:1440px;margin:0 auto;padding:32px 28px 64px}.hero{display:flex;justify-content:space-between;align-items:flex-end;gap:24px;padding:22px 4px 28px}.eyebrow{text-transform:uppercase;letter-spacing:.16em;font-size:11px;font-weight:800;color:var(--teal)}h1{font-size:clamp(30px,4vw,48px);line-height:1.06;letter-spacing:-.04em;margin:10px 0}.hero p{max-width:720px;margin:0;color:var(--muted);line-height:1.6}.hero-mark{font-size:44px;line-height:1;background:#d8eeee;border-radius:20px;padding:18px}.layout{display:grid;grid-template-columns:320px minmax(0,1fr);gap:20px;align-items:start}.panel{background:var(--paper);border:1px solid var(--line);border-radius:18px;box-shadow:var(--shadow)}.controls{padding:22px;position:sticky;top:16px}.panel h2{font-size:17px;margin:0 0 16px;letter-spacing:-.02em}.field{margin:0 0 17px}.field label{display:block;font-size:12px;font-weight:800;margin-bottom:7px;color:#36505f}.field input,.field select{width:100%;border:1px solid #cbd8dd;background:white;border-radius:10px;padding:11px 12px;color:var(--ink)}.hint{font-size:11px;color:var(--muted);line-height:1.45;margin-top:6px}.btn{border:0;border-radius:10px;padding:11px 15px;font-weight:800;background:var(--teal);color:white;transition:.15s}.btn:hover{background:var(--teal-dark);transform:translateY(-1px)}.btn:disabled{opacity:.55;cursor:wait;transform:none}.btn.secondary{background:#e7f1f2;color:#116c70}.btn.ghost{background:white;color:var(--teal);border:1px solid #b8d3d4}.btn.small{padding:8px 10px;font-size:12px}.btnrow{display:flex;gap:8px;flex-wrap:wrap}.devicebox{padding:12px;border-radius:12px;background:#f4f8f8;margin-top:14px;font-size:12px;line-height:1.5;min-height:54px}.notice{margin:14px 0 0;padding:12px;border-radius:10px;background:#fff5df;color:#76540d;font-size:11px;line-height:1.5}.maincol{min-width:0}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px}.stat{padding:15px 17px}.stat b{display:block;font-size:24px;letter-spacing:-.04em}.stat span{font-size:11px;color:var(--muted);font-weight:700}.catalog{padding:20px}.toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.toolbar h2{margin:0}.filters{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:16px 0}.filters input,.filters select{border:1px solid var(--line);border-radius:9px;padding:9px 10px;background:white;color:var(--ink)}.filters input{flex:1;min-width:190px}.tabs{display:flex;gap:6px;flex-wrap:wrap}.tab{border:1px solid var(--line);background:white;color:#526672;border-radius:20px;padding:8px 12px;font-size:12px;font-weight:800}.tab.active{background:var(--ink);border-color:var(--ink);color:white}.list{display:grid;gap:8px;max-height:680px;overflow:auto;padding:2px}.case{display:grid;grid-template-columns:22px minmax(0,1fr) auto;gap:11px;align-items:start;border:1px solid #e3ebed;border-radius:12px;padding:12px;background:#fff}.case:hover{border-color:#b5d5d7}.case input{margin:3px 0 0;accent-color:var(--teal);width:16px;height:16px}.case h3{margin:0;font-size:13px}.case p{margin:4px 0 0;color:var(--muted);font-size:11px;line-height:1.45}.tag{display:inline-flex;align-items:center;border-radius:20px;padding:4px 8px;font-size:10px;font-weight:800;background:#edf3f5;color:#536976;white-space:nowrap}.tag.android{background:#e7f4eb;color:#34734a}.countline{color:var(--muted);font-size:12px}.results{margin-top:16px;padding:20px}.results-head{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.results-head h2{margin:0}.result-summary{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.pill{border-radius:20px;background:#f0f4f5;padding:7px 10px;font-size:11px;font-weight:800}.passed{color:var(--green)}.failed{color:var(--red)}.skipped{color:var(--amber)}.result-list{display:grid;gap:8px;max-height:540px;overflow:auto}.result{border:1px solid var(--line);border-radius:11px;padding:12px}.result-top{display:flex;justify-content:space-between;gap:12px;align-items:center}.result h3{margin:0;font-size:13px}.result p{margin:6px 0;color:var(--muted);font-size:11px;line-height:1.45}.result small{color:#637481}.empty{padding:32px 12px;text-align:center;color:var(--muted);font-size:13px}.progress{height:4px;background:#e7eeee;border-radius:9px;overflow:hidden;margin:12px 0}.progress span{display:block;width:0;height:100%;background:var(--teal);transition:width .2s}.footnote{font-size:11px;color:var(--muted);line-height:1.6;margin-top:16px}
@media(max-width:940px){.layout{grid-template-columns:1fr}.controls{position:static}.stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){.shell{padding:20px 12px 40px}.hero{align-items:flex-start}.hero-mark{font-size:28px;padding:12px}.stats{gap:8px}.stat{padding:12px}.case{grid-template-columns:20px minmax(0,1fr)}.case .tag{grid-column:2;justify-self:start}.catalog,.results{padding:15px}}
</style>
</head>
<body><main class="shell">
<header class="hero"><div><div class="eyebrow">Device validation workspace</div><h1>Connectivity lab</h1><p>Browse Android-focused Bluetooth and Wi-Fi scenarios, select a focused test run, and inspect adapter evidence. Unknown or unavailable device signals are reported as skipped—not guessed.</p></div><div class="hero-mark" aria-hidden="true">◉</div></header>
<div class="layout">
<aside class="panel controls"><h2>Run setup</h2>
<div class="field"><label for="adapter">Test adapter</label><select id="adapter"><option value="fake">Demo / fake device</option><option value="real">Host BLE device (Bleak)</option><option value="android">Android phone via ADB</option></select><div class="hint">ADB mode reads Android Wi-Fi/radio state. It does not toggle radios or initiate pairing.</div></div>
<div class="field" id="filter-field"><label for="filter">BLE device name filter</label><input id="filter" placeholder="e.g. Ray-Ban Meta"><div class="hint">Used with the host Bluetooth adapter.</div></div>
<div class="field" id="serial-field" hidden><label for="serial">ADB serial (optional)</label><input id="serial" placeholder="auto-select if one device"><div class="hint">Enable USB or wireless debugging and authorize this computer on the phone.</div></div>
<div class="btnrow"><button class="btn" id="discover-btn" type="button">Discover BLE devices</button></div><div class="devicebox" id="devicebox" role="status">No discovery run yet.</div>
<div class="notice"><b>Android test limits:</b> Android 12+ Bluetooth scan/connect permissions, Wi-Fi location/nearby permissions, OEM privacy rules, and hidden controller state can restrict data. GATT, Classic profiles, roaming, and RF tests need a native instrumentation app and/or dedicated peer/AP fixtures.</div>
</aside>
<section class="maincol">
<div class="stats"><div class="panel stat"><b id="stat-total">—</b><span>SCENARIOS IN CATALOG</span></div><div class="panel stat"><b id="stat-bt">—</b><span>BLUETOOTH</span></div><div class="panel stat"><b id="stat-wifi">—</b><span>WI-FI</span></div><div class="panel stat"><b id="stat-run">—</b><span>LAST RUN</span></div></div>
<section class="panel catalog"><div class="toolbar"><h2>Test catalog</h2><span class="countline" id="visible-count">Loading scenarios…</span></div>
<div class="filters"><input id="search" type="search" placeholder="Search scenarios, permissions, features…" aria-label="Search tests"><select id="category" aria-label="Filter by category"><option value="">All categories</option></select></div>
<div class="filters"><div class="tabs" role="group" aria-label="Test domain"><button class="tab active" data-domain="all">All tests</button><button class="tab" data-domain="Bluetooth">Bluetooth</button><button class="tab" data-domain="Wi-Fi">Wi-Fi</button></div><div class="btnrow" style="margin-left:auto"><button class="btn ghost small" id="select-visible" type="button">Select visible</button><button class="btn ghost small" id="clear-selection" type="button">Clear</button></div></div>
<div class="filters" aria-label="Quick test presets"><div class="tabs"><button class="tab" id="preset-smoke" type="button">Quick smoke</button><button class="tab" id="preset-bluetooth" type="button">BLE basics</button><button class="tab" id="preset-wifi" type="button">Wi-Fi basics</button></div><span class="countline">Presets replace the current selection.</span></div>
<div class="list" id="catalog-list"><div class="empty">Loading catalog…</div></div>
<div class="progress" aria-hidden="true"><span id="progress-bar"></span></div>
<div class="btnrow"><button class="btn" id="run-selected" type="button">Run selected (0)</button><button class="btn secondary" id="run-all" type="button">Run all scenarios</button></div>
<p class="footnote">Safety: this dashboard runs read-only status checks by default. Tests requiring radio toggles, credential changes, roaming, sustained traffic, pairing UI, or destructive settings changes are catalogued with their required fixtures and are skipped until a capable adapter explicitly reports evidence.</p>
</section>
<section class="panel results"><div class="results-head"><h2>Run results</h2><button class="btn ghost small" id="export-results" type="button" disabled>Export JSON</button></div><div class="result-summary" id="result-summary"><span class="pill">No run yet</span></div><div class="result-list" id="result-list"><div class="empty">Select scenarios and run a test to see evidence here.</div></div></section>
</section></div></main>
<script>
const $=id=>document.getElementById(id);let catalog=[];let selectedAddress=null;let activeDomain='all';let lastResults=[];let busy=false;
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
async function request(url,options){const response=await fetch(url,options);const data=await response.json();if(!response.ok)throw new Error(data.error||`Request failed (${response.status})`);return data;}
function adapterChanged(){const android=$('adapter').value==='android';const real=$('adapter').value==='real';$('serial-field').hidden=!android;$('filter-field').hidden=!real;$('discover-btn').disabled=android;$('discover-btn').textContent=android?'BLE scan unavailable in ADB mode':'Discover BLE devices';$('devicebox').textContent=android?'Android ADB mode can run read-only phone Wi-Fi/radio checks; peer scanning requires native instrumentation.':'No discovery run yet.';selectedAddress=null;}
function filteredCatalog(){const q=$('search').value.trim().toLowerCase();const category=$('category').value;return catalog.filter(item=>(activeDomain==='all'||item.domain===activeDomain)&&(!category||item.category===category)&&(!q||`${item.id} ${item.title} ${item.description} ${item.requirement} ${item.category}`.toLowerCase().includes(q)));}
function renderCatalog(){const items=filteredCatalog();$('visible-count').textContent=`${items.length} shown · ${selectedIds().length} selected`;if(!items.length){$('catalog-list').innerHTML='<div class="empty">No scenarios match the current filters.</div>';updateRunButtons();return;}$('catalog-list').innerHTML=items.map(item=>`<label class="case"><input type="checkbox" class="case-check" value="${esc(item.id)}" ${item.selected?'checked':''}><span><h3>${esc(item.title||item.id)}</h3><p>${esc(item.description||'Adapter-based connectivity validation.')}</p><p><b>Needs:</b> ${esc(item.requirement||'Adapter-reported test evidence')}</p></span><span class="tag ${item.mode==='adapter'?'android':''}">${esc(item.category)}</span></label>`).join('');document.querySelectorAll('.case-check').forEach(box=>box.addEventListener('change',()=>{const item=catalog.find(candidate=>candidate.id===box.value);if(item)item.selected=box.checked;updateRunButtons();}));updateRunButtons();}
function selectedIds(){return catalog.filter(item=>item.selected).map(item=>item.id);}
function updateRunButtons(){const count=selectedIds().length;$('run-selected').textContent=`Run selected (${count})`;$('run-selected').disabled=busy||count===0;$('run-all').disabled=busy;updateSelectionCount();}
function updateSelectionCount(){$('visible-count').textContent=`${filteredCatalog().length} shown · ${selectedIds().length} selected`;try{localStorage.setItem('connectivity-lab-selection',JSON.stringify(selectedIds()));}catch(error){console.debug('Selection persistence unavailable',error);}}
function applyPreset(ids){const selected=new Set(ids);catalog.forEach(item=>item.selected=selected.has(item.id));renderCatalog();}
function presetIds(kind){const exact={smoke:['bluetooth_discovery','bluetooth_connect','bluetooth_reconnect','wifi_connected','wifi_ip_configured','wifi_gateway_configured','wifi_dns_configured','wifi_signal_quality'],bluetooth:['bluetooth_discovery','bluetooth_connect','bluetooth_reconnect','bluetooth_pairing_auth','bluetooth_signal_quality','bluetooth_connection_drop','bluetooth_gatt_service_discovery','bluetooth_gatt_read','bluetooth_gatt_write','bluetooth_gatt_notifications'],wifi:['wifi_connected','wifi_ip_configured','wifi_ipv6_address','wifi_gateway_configured','wifi_dns_configured','wifi_dns_resolution','wifi_signal_quality','wifi_internet_reachability','wifi_network_probe','wifi_reconnect']};return exact[kind]||[];}
function updateCategories(){const categories=[...new Set(catalog.filter(item=>activeDomain==='all'||item.domain===activeDomain).map(item=>item.category))].sort();const current=$('category').value;$('category').innerHTML='<option value="">All categories</option>'+categories.map(name=>`<option value="${esc(name)}">${esc(name)}</option>`).join('');if(categories.includes(current))$('category').value=current;}
async function loadCatalog(){try{const data=await request('/api/catalog');let saved=[];try{saved=JSON.parse(localStorage.getItem('connectivity-lab-selection')||'[]');}catch(error){console.debug('Saved selection unavailable',error);}const savedSet=new Set(saved);catalog=data.scenarios.map(item=>({...item,selected:savedSet.has(item.id)}));$('stat-total').textContent=catalog.length;$('stat-bt').textContent=catalog.filter(item=>item.domain==='Bluetooth').length;$('stat-wifi').textContent=catalog.filter(item=>item.domain==='Wi-Fi').length;updateCategories();renderCatalog();}catch(error){$('catalog-list').innerHTML=`<div class="empty">Could not load scenario catalog: ${esc(error.message)}</div>`;}}
async function discover(){const adapter=$('adapter').value;if(adapter==='android')return;const box=$('devicebox');box.textContent='Scanning…';$('discover-btn').disabled=true;try{const params=new URLSearchParams({adapter,filter:$('filter').value});const data=await request('/api/discover?'+params);selectedAddress=data.devices[0]?.address||null;box.innerHTML=data.devices.length?data.devices.map((device,index)=>`<label style="display:block;padding:6px 0"><input type="radio" name="device" value="${esc(device.address)}" ${index===0?'checked':''}> <b>${esc(device.name)}</b><br><span>${esc(device.address)} · RSSI ${esc(device.rssi??'n/a')} dBm</span></label>`).join(''):`${esc(data.error||'No BLE devices found.')}`;document.querySelectorAll('input[name="device"]').forEach(radio=>radio.addEventListener('change',()=>selectedAddress=radio.value));}catch(error){box.textContent=error.message;}finally{$('discover-btn').disabled=false;}}
function showResults(items){lastResults=items;$('export-results').disabled=!items.length;$('stat-run').textContent=items.length;const counts={passed:0,failed:0,skipped:0};for(const item of items)counts[item.status]=(counts[item.status]||0)+1;$('result-summary').innerHTML=`<span class="pill passed">${counts.passed} passed</span><span class="pill failed">${counts.failed} failed</span><span class="pill skipped">${counts.skipped} skipped</span><span class="pill">${items.length} total</span>`;$('result-list').innerHTML=items.map(item=>`<article class="result"><div class="result-top"><h3>${esc(item.title||item.name)}</h3><span class="status ${esc(item.status)}">${esc(item.status).toUpperCase()}</span></div><p>${esc(item.message)}</p><small>${esc(item.domain)} · ${esc(item.category)} · ${Number(item.duration_ms||0).toFixed(1)} ms${item.requirement?` · Requires: ${esc(item.requirement)}`:''}</small></article>`).join('')||'<div class="empty">No results returned.</div>';}
async function run(ids){if(busy)return;busy=true;updateRunButtons();$('progress-bar').style.width='35%';$('result-list').innerHTML='<div class="empty">Running selected adapter checks…</div>';try{const data=await request('/api/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({adapter:$('adapter').value,filter:$('filter').value,address:selectedAddress,serial:$('serial').value,case_ids:ids})});$('progress-bar').style.width='100%';showResults(data.results||[]);}catch(error){$('progress-bar').style.width='0';$('result-list').innerHTML=`<div class="empty">Run failed: ${esc(error.message)}</div>`;}finally{busy=false;setTimeout(()=>$('progress-bar').style.width='0',700);updateRunButtons();}}
$('adapter').addEventListener('change',adapterChanged);$('discover-btn').addEventListener('click',discover);$('search').addEventListener('input',renderCatalog);$('category').addEventListener('change',renderCatalog);document.querySelectorAll('.tab[data-domain]').forEach(button=>button.addEventListener('click',()=>{activeDomain=button.dataset.domain;document.querySelectorAll('.tab[data-domain]').forEach(tab=>tab.classList.toggle('active',tab===button));updateCategories();renderCatalog();}));$('select-visible').addEventListener('click',()=>{filteredCatalog().forEach(item=>item.selected=true);renderCatalog();});$('clear-selection').addEventListener('click',()=>{catalog.forEach(item=>item.selected=false);renderCatalog();});$('preset-smoke').addEventListener('click',()=>applyPreset(presetIds('smoke')));$('preset-bluetooth').addEventListener('click',()=>applyPreset(presetIds('bluetooth')));$('preset-wifi').addEventListener('click',()=>applyPreset(presetIds('wifi')));$('run-selected').addEventListener('click',()=>run(selectedIds()));$('run-all').addEventListener('click',()=>{if(catalog.length>80&&!confirm(`Run all ${catalog.length} scenarios? Many Android hardware scenarios may be skipped without permissions, peers, and lab fixtures.`))return;run(catalog.map(item=>item.id));});$('export-results').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(lastResults,null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='connectivity-test-results.json';link.click();URL.revokeObjectURL(link.href);});adapterChanged();loadCatalog();
</script></body></html>'''
